static size_t fused_call(implementation i,const uint8_t*raw,size_t raw_len,uint32_t*out,size_t n,sdat_stats*st,size_t*used){bytes_ctx c={raw,raw_len,0};size_t got=i==ORIGINAL?falcon_original_gaussian0_sample_n(bytes_cb,&c,out,n,st):falcon_sda_gaussian0_sample_n(bytes_cb,&c,out,n,st);if(used)*used=c.pos;return got;}
static int staged_call(implementation i,const uint8_t*raw,size_t raw_len,uint32_t*out,size_t n,size_t block,falcon_stage_workspace*ws,sdat_stats*st,falcon_stage_timing*tm){return i==ORIGINAL?falcon_original_block_staged_sample_n(out,n,raw,raw_len,block,ws,st,tm):falcon_sda_block_staged_sample_n(out,n,raw,raw_len,block,ws,st,tm);}
static measurement measure_fused(implementation i,const uint8_t*raw,size_t raw_len,uint32_t*out,uint32_t*replay,size_t n){measurement m={0};uint64_t a=bench_timer_start();size_t got=fused_call(i,raw,raw_len,out,n,0,0);uint64_t b=bench_timer_stop();m.cycles=b-a;m.checksum=falcon_base_checksum(out,n);sdat_stats st={0};size_t used=0,again=fused_call(i,raw,raw_len,replay,n,&st,&used);m.replay=falcon_base_checksum(replay,n);m.attempts=(size_t)st.attempts;m.rejections=(size_t)st.rejections;m.words=used/FALCON_BASE_RANDOM_BYTES;if(got!=n||again!=n||m.checksum!=m.replay)m.status=-1;return m;}
static measurement measure_staged(implementation i,const uint8_t*raw,size_t raw_len,uint32_t*out,uint32_t*replay,size_t n,size_t block,falcon_stage_workspace*ws){measurement m={0};uint64_t a=bench_timer_start();m.status=staged_call(i,raw,raw_len,out,n,block,ws,0,0);uint64_t b=bench_timer_stop();m.cycles=b-a;m.checksum=falcon_base_checksum(out,n);sdat_stats st={0};int rc=staged_call(i,raw,raw_len,replay,n,block,ws,&st,0);m.replay=falcon_base_checksum(replay,n);m.attempts=(size_t)st.attempts;m.rejections=(size_t)st.rejections;m.words=(size_t)(st.random_bytes/FALCON_BASE_RANDOM_BYTES);if(rc||m.checksum!=m.replay)m.status=-1;return m;}
static uint64_t mark(void*ctx){(void)ctx;return bench_timer_mark();}
static void run_all(implementation i,const uint8_t*raw,size_t raw_len,uint32_t*out,uint32_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,size_t block,falcon_stage_workspace*ws,int rows){measurement fused=measure_fused(i,raw,raw_len,out,replay,n),staged=measure_staged(i,raw,raw_len,out,replay,n,block,ws);if(fused.checksum!=staged.checksum||fused.attempts!=staged.attempts||fused.rejections!=staged.rejections||fused.words!=staged.words)fused.status=staged.status=-2;falcon_stage_timing tm={mark,0,0,0,0};int status=staged_call(i,raw,raw_len,out,n,block,ws,0,&tm);uint64_t ck=falcon_base_checksum(out,n);sdat_stats st={0};int rc=staged_call(i,raw,raw_len,replay,n,block,ws,&st,0);uint64_t rck=falcon_base_checksum(replay,n),reconstructed=tm.input_cycles+tm.mapping_cycles;if(rc||ck!=rck||ck!=staged.checksum||st.attempts!=staged.attempts||st.rejections!=staged.rejections||st.random_bytes/FALCON_BASE_RANDOM_BYTES!=staged.words)status=-3;if(reconstructed>tm.outer_cycles)status=-4;if(!rows)return;char scpo[32],fcpo[32],difference[32];snprintf(scpo,sizeof scpo,"%.6f",(double)staged.cycles/n);snprintf(fcpo,sizeof fcpo,"%.6f",(double)fused.cycles/n);snprintf(difference,sizeof difference,"%.6f",100.0*((double)staged.cycles/fused.cycles-1));const char*pv=i==ORIGINAL?"official-falcon-reverse-tail":"sda-falcon-reverse-tail-accept-before-map";row fr={i,"full-sampler-fused",pv,"first","fused","na","false",n,proc,rep,block,seed,fused.cycles,fused.checksum,fused.replay,0,0,0,fused.attempts,fused.rejections,fused.words,fused.status,"na","na","na","na"};row sr={i,"full-sampler-block-staged","block-staged","second","block-staged","total","false",n,proc,rep,block,seed,staged.cycles,staged.checksum,staged.replay,0,0,0,staged.attempts,staged.rejections,staged.words,staged.status,scpo,fcpo,"na",difference};uint64_t uncovered=tm.outer_cycles-reconstructed;row in={i,"block-stage-input","block-staged","first","block-staged","input","true",n,proc,rep,block,seed,tm.input_cycles,ck,rck,reconstructed,tm.outer_cycles,uncovered,(size_t)st.attempts,(size_t)st.rejections,(size_t)(st.random_bytes/FALCON_BASE_RANDOM_BYTES),status,"na","na","na","na"};row mp={i,"block-stage-mapping","block-staged","second","block-staged","mapping","true",n,proc,rep,block,seed,tm.mapping_cycles,ck,rck,reconstructed,tm.outer_cycles,uncovered,(size_t)st.attempts,(size_t)st.rejections,(size_t)(st.random_bytes/FALCON_BASE_RANDOM_BYTES),status,"na","na","na","na"};emit(&fr);emit(&sr);emit(&in);emit(&mp);}
static void run_case(implementation i,size_t n,size_t proc,size_t rep,size_t block,int rows){size_t attempts=n*2+4096,raw_len=attempts*FALCON_BASE_RANDOM_BYTES;uint8_t*raw=malloc(raw_len);uint32_t*out=malloc(n*sizeof*out),*replay=malloc(n*sizeof*replay);falcon_u72_limbs*candidates=malloc(block*sizeof*candidates);if(!raw||!out||!replay||!candidates)exit(2);uint64_t seed=frodo_benchmark_seed(0,proc,rep,3);frodo_benchmark_fill_bytes(raw,raw_len,seed);falcon_stage_workspace ws={candidates,block};run_all(i,raw,raw_len,out,replay,n,proc,rep,seed,block,&ws,rows);free(raw);free(out);free(replay);free(candidates);}
int main(void){const char*selection=env_string("FALCON_BENCH_IMPLEMENTATION","all");size_t reps=env_size("FALCON_BENCH_REPETITIONS",31),warm=env_size("FALCON_BENCH_WARMUP",5),n=env_size("FALCON_BENCH_SAMPLE_COUNT",1048576),proc=env_size("FALCON_BENCH_PROCESS_INDEX",0),block=env_size("FALCON_STAGE_BLOCK_SIZE",DEFAULT_BLOCK);if(!block){fprintf(stderr,"FALCON_STAGE_BLOCK_SIZE must be positive\n");return 2;}puts(header);for(int ii=0;ii<2;ii++){implementation i=(implementation)ii;if(strcmp(selection,"all")&&strcmp(selection,ii?"sda":"original"))continue;for(size_t w=0;w<warm;w++)run_case(i,n,proc,w,block,0);for(size_t rep=0;rep<reps;rep++)run_case(i,n,proc,rep,block,1);}return 0;}
